const MAX_RETRIES = 60;
const item = $input.first().json;
const status = item.status;
const retryCount = (item._retryCount || 0) + 1;

if (status === 'complete') {
  return [{ json: { ...item, _result: 'complete' } }];
}

if (status === 'failed' || status === 'error') {
  return [{ json: { ...item, _result: 'failed', _error: item.error || 'Job reported failure' } }];
}

if (retryCount >= MAX_RETRIES) {
  return [{ json: { ...item, _result: 'failed', _error: 'Transcription polling timed out after ' + MAX_RETRIES + ' attempts' } }];
}

return [{ json: { ...item, _result: 'pending', _retryCount: retryCount } }];

const transcriptData = $('Poll Transcription Status').first().json;
const videoId = $('Workflow Trigger').first().json.video_id;
return [{ json: {
  transcript: transcriptData.result ? transcriptData.result.full_text : '',
  video_id: videoId
} }];

const MAX_RETRIES = 40;
const item = $input.first().json;
const status = item.status;
const retryCount = (item._retryCount || 0) + 1;

if (status === 'complete') {
  return [{ json: { ...item, _result: 'complete' } }];
}

if (status === 'failed' || status === 'error') {
  return [{ json: { ...item, _result: 'failed', _error: item.error || 'Job reported failure' } }];
}

if (retryCount >= MAX_RETRIES) {
  return [{ json: { ...item, _result: 'failed', _error: 'Chart extraction polling timed out after ' + MAX_RETRIES + ' attempts' } }];
}

return [{ json: { ...item, _result: 'pending', _retryCount: retryCount } }];

// Combine transcript + chart URLs for LLM pipeline
const charts = ($('Poll Chart Extraction Status').first().json.result && $('Poll Chart Extraction Status').first().json.result.charts)
  ? $('Poll Chart Extraction Status').first().json.result.charts
  : [];
let video_title = '';
try { video_title = $('Pick Caption Credential').first().json.video_title || ''; } catch (e) { video_title = ''; }
return [{ json: {
  video_id: $('Store Transcript Data').first().json.video_id,
  transcript: $('Store Transcript Data').first().json.transcript,
  chart_urls: charts,
  channel_id: $('Workflow Trigger').first().json.channel_id || '',
  video_title: video_title
} }];

// Transcript only, no charts available
let video_title = '';
try { video_title = $('Pick Caption Credential').first().json.video_title || ''; } catch (e) { video_title = ''; }
return [{ json: {
  video_id: $('Store Transcript Data').first().json.video_id,
  transcript: $('Store Transcript Data').first().json.transcript,
  chart_urls: [],
  channel_id: $('Workflow Trigger').first().json.channel_id || '',
  video_title: video_title
} }];

// Store cloud transcript - handles all items (multiple videos)
const items = $input.all();
return items.map(item => {
  const data = item.json;
  const videoId = data.video_id || '';

  if (data.cloud_fallback_failed || data.error || !data.transcript) {
    return {
      json: {
        transcript: '',
        video_id: videoId,
        cloud_fallback_failed: true,
        error: data.error || 'Cloud transcription failed'
      }
    };
  }

  return {
    json: {
      transcript: data.transcript,
      video_id: videoId,
      source: data.source || 'cloud',
      char_count: data.char_count || data.transcript.length
    }
  };
});

// Cloud path: package data for LLM Pipeline
// Filters out failed items, stops chain if no transcripts
const items = $input.all();
let video_title = '';
try { video_title = $('Pick Caption Credential').first().json.video_title || ''; } catch (e) { video_title = ''; }
return items
  .filter(item => !item.json.cloud_fallback_failed && item.json.transcript)
  .map(item => ({
    json: {
      video_id: item.json.video_id,
      transcript: item.json.transcript,
      chart_urls: [],
      channel_id: $('Workflow Trigger').first().json.channel_id || '',
      video_title: video_title
    }
  }));

// Extract best caption track ID from YouTube Data API captions.list response
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const video_id = $('Workflow Trigger').first().json.video_id || '';

  try {
    const allTracks = data.items || [];
    // Guard: skip tracks with status 'failed' -- YouTube lists them but the download
    // is a useless ~515-byte stub even for the owning channel.
    const tracks = allTracks.filter(t => t && t.snippet && String(t.snippet.status || '').toLowerCase() !== 'failed');
    if (tracks.length === 0) {
      const why = allTracks.length > 0
        ? 'All ' + allTracks.length + ' caption track(s) have status failed for video ' + video_id
        : 'No caption tracks found for video ' + video_id;
      results.push({ json: { video_id, captionId: '', cloud_fallback_failed: true, error: why } });
      continue;
    }

    // Filter to serving tracks first; fall back to all tracks if none are serving
    const servingTracks = tracks.filter(t => t.snippet.status === 'serving');
    const pool = servingTracks.length > 0 ? servingTracks : tracks;

    // Priority: manual English > auto-generated English > any English-like > first available
    let best = pool.find(t => t.snippet.language === 'en' && t.snippet.trackKind !== 'ASR')
      || pool.find(t => t.snippet.language === 'en' && t.snippet.trackKind === 'ASR')
      || pool.find(t => t.snippet.language && t.snippet.language.startsWith('en'))
      || pool[0];

    results.push({
      json: {
        captionId: best.id,
        language: best.snippet.language,
        trackKind: best.snippet.trackKind || 'standard',
        status: best.snippet.status || 'unknown',
        video_id
      }
    });
  } catch (e) {
    results.push({ json: { video_id, captionId: '', cloud_fallback_failed: true, error: 'Caption extract error: ' + e.message } });
  }
}

return results;

// Build Transcript — handles BOTH timedtext json3 (primary, ASR-capable)
// and captions.download SRT (fallback). Never stringifies arbitrary objects.
const items = $input.all();

let extractMeta = [];
try { extractMeta = $('Extract Caption URL').all(); } catch (e) { extractMeta = []; }

function resolveVideoId(data, i) {
  if (data && data.video_id) return data.video_id;
  try { const v = $('Workflow Trigger').first().json.video_id; if (v) return v; } catch (e) {}
  try { const m = extractMeta[i] && extractMeta[i].json; if (m && m.video_id) return m.video_id; } catch (e) {}
  return '';
}

const results = [];

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;
  const meta = (extractMeta[i] && extractMeta[i].json) || {};
  const video_id = resolveVideoId(data, i);

  // Upstream failure: never fabricate a transcript
  if (data.error || data.cloud_fallback_failed || meta.cloud_fallback_failed) {
    const reason = (typeof data.error === 'string' && data.error)
      || (typeof meta.error === 'string' && meta.error)
      || 'Upstream caption fetch failed';
    results.push({ json: { video_id, transcript: '', cloud_fallback_failed: true, error: reason } });
    continue;
  }

  // Only accept STRING payloads
  const payload = typeof data === 'string'
    ? data
    : (typeof data.data === 'string' ? data.data
      : (typeof data.body === 'string' ? data.body : ''));

  if (!payload) {
    results.push({ json: { video_id, transcript: '', cloud_fallback_failed: true, error: 'Empty caption response' } });
    continue;
  }

  let transcript = '';
  let source = '';
  const trimmed = payload.trimStart();

  if (trimmed.startsWith('{')) {
    source = 'timedtext_json3';
    let parsed = null;
    try { parsed = JSON.parse(trimmed); } catch (e) { parsed = null; }
    if (!parsed || !Array.isArray(parsed.events)) {
      results.push({ json: { video_id, transcript: '', cloud_fallback_failed: true, error: 'Caption endpoint returned JSON without events / error payload' } });
      continue;
    }
    transcript = parsed.events
      .flatMap(e => (e.segs || []).map(s => s.utf8 || ''))
      .join('')
      .replace(/\n/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  } else {
    source = 'captions_download_srt';
    const lines = payload.split('\n');
    const textLines = [];
    for (const line of lines) {
      const t = line.trim();
      if (!t) continue;
      if (/^\d+$/.test(t)) continue;
      if (/\d{2}:\d{2}:\d{2}[,.]\d{3}\s*-->\s*\d{2}:\d{2}:\d{2}[,.]\d{3}/.test(t)) continue;
      textLines.push(t.replace(/<[^>]+>/g, ''));
    }
    transcript = textLines.join(' ').replace(/\s+/g, ' ').trim();
  }

  if (transcript.length <= 1000) {
    results.push({ json: { video_id, transcript: '', cloud_fallback_failed: true, error: 'Transcript too short (' + transcript.length + ' chars) — likely invalid' } });
    continue;
  }

  results.push({ json: { transcript, video_id, source, char_count: transcript.length } });
}

return results;

// Extract the best timedtext caption track URL from a YouTube watch page.
// Primary path for the cloud transcript pipeline (works for ASR/auto tracks).
const items = $input.all();
const results = [];

function balancedPlayerResponse(html) {
  const key = 'ytInitialPlayerResponse';
  const idx = html.indexOf(key);
  if (idx === -1) return null;
  const start = html.indexOf('{', idx);
  if (start === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < html.length; i++) {
    const ch = html[i];
    if (inStr) {
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
    } else if (ch === '"') inStr = true;
    else if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) return html.slice(start, i + 1); }
  }
  return null;
}

for (const item of items) {
  const data = item.json;
  let video_id = data.video_id || '';
  if (!video_id) {
    try { video_id = $('Workflow Trigger').first().json.video_id || ''; } catch (e) {}
  }

  const html = typeof data === 'string'
    ? data
    : (typeof data.data === 'string' ? data.data
      : (typeof data.body === 'string' ? data.body : ''));

  const fail = (error) => results.push({ json: { video_id, cloud_fallback_failed: true, use_api_fallback: true, error } });

  if (!html) { fail('Empty watch page response'); continue; }
  if (/consent\.youtube\.com|\/consent\?|action_recaptcha|"consentBumpV2"|"BOT_DETECTED"/.test(html)) {
    fail('consent/bot wall detected'); continue;
  }

  // 1) Direct captionTracks array
  let tracks = null;
  const m = html.match(/"captionTracks":(\[.*?\])(?:,"|\])/s);
  if (m) {
    try { tracks = JSON.parse(m[1].replace(/\\u0026/g, '&')); } catch (e) { tracks = null; }
  }

  // 2) Fallback: full ytInitialPlayerResponse (brace-balanced)
  if (!Array.isArray(tracks) || tracks.length === 0) {
    const raw = balancedPlayerResponse(html);
    if (raw) {
      try {
        const player = JSON.parse(raw);
        const ct = player && player.captions
          && player.captions.playerCaptionsTracklistRenderer
          && player.captions.playerCaptionsTracklistRenderer.captionTracks;
        if (Array.isArray(ct)) tracks = ct;
      } catch (e) {}
    }
  }

  if (!Array.isArray(tracks) || tracks.length === 0) {
    fail('captionTracks not found in page'); continue;
  }

  const isAsr = (t) => t.kind === 'asr' || (typeof t.vssId === 'string' && t.vssId.indexOf('a.') === 0);
  const lc = (t) => t.languageCode || '';

  const best = tracks.find(t => !isAsr(t))
    || tracks.find(t => isAsr(t) && lc(t).indexOf('hi') === 0)
    || tracks.find(t => isAsr(t) && lc(t).indexOf('en') === 0)
    || tracks[0];

  let baseUrl = (best && best.baseUrl) ? String(best.baseUrl) : '';
  baseUrl = baseUrl.replace(/\\u0026/g, '&').replace(/\\\//g, '/');

  if (!baseUrl) { fail('caption track missing baseUrl'); continue; }

  results.push({ json: { video_id, timedtext_url: baseUrl + '&fmt=json3' } });
}

return results;

// Extract best caption track from InnerTube (ANDROID) player response.
// PRIMARY cloud caption route: ASR-capable, returns baseUrls that work from datacenter IPs.
const items = $input.all();
const results = [];

for (const item of items) {
  const json = item.json || {};
  let video_id = json.video_id || '';
  if (!video_id) {
    try { video_id = $('Workflow Trigger').first().json.video_id || ''; } catch (e) {}
  }

  const ct = json.captions
    && json.captions.playerCaptionsTracklistRenderer
    && json.captions.playerCaptionsTracklistRenderer.captionTracks;
  const tracks = Array.isArray(ct) ? ct : [];

  if (tracks.length === 0) {
    const status = (json.playabilityStatus && json.playabilityStatus.status) || 'unknown';
    results.push({ json: {
      video_id,
      cloud_fallback_failed: true,
      use_scrape_fallback: true,
      error: 'InnerTube: no captionTracks (playabilityStatus: ' + status + ')'
    } });
    continue;
  }

  const isAsr = (t) => t.kind === 'asr';
  const lc = (t) => t.languageCode || '';

  const best = tracks.find(t => !isAsr(t))
    || tracks.find(t => isAsr(t) && lc(t).indexOf('hi') === 0)
    || tracks.find(t => isAsr(t) && lc(t).indexOf('en') === 0)
    || tracks[0];

  const baseUrl = (best && best.baseUrl) ? String(best.baseUrl) : '';
  if (!baseUrl) {
    results.push({ json: {
      video_id,
      cloud_fallback_failed: true,
      use_scrape_fallback: true,
      error: 'InnerTube: caption track present but missing baseUrl'
    } });
    continue;
  }

  const timedtext_url = baseUrl.indexOf('fmt=') !== -1 ? baseUrl : baseUrl + '&fmt=json3';
  results.push({ json: { video_id, timedtext_url } });
}

return results;

// Decide which YouTube OAuth credential can download captions for this video.
// captions.download only works for the OWNING channel, and the queue mixes two
// channels, so resolve snippet.channelId from videos.list and map it to a branch.
// This node NEVER throws: on any failure it defaults to 'hitpoint' (all currently
// queued content is Hitpoint Live owned) and flags channel_resolved: false.
const CHANNEL_MAP = {
  'UCyFDhiqKcVqoIGB3CmJJFUg': 'hitpoint',
  'UC9VKHMUGg5gqSebXW1m5GBw': 'tws'
};
const DEFAULT_OWNER = 'hitpoint';

let video_id = '';
try { video_id = $('Workflow Trigger').first().json.video_id || ''; } catch (e) { video_id = ''; }

let channel_id = '';
let video_title = '';
let channel_resolved = false;
let resolve_error = '';

try {
  const first = $input.first();
  const data = (first && first.json) || {};

  // Resolve Channel runs with onError: continueRegularOutput, so a 4xx/5xx or
  // timeout arrives here as an error-shaped item rather than aborting the run.
  if (data.error) {
    resolve_error = typeof data.error === 'string'
      ? data.error
      : (data.error.message || 'videos.list returned an error');
  }

  const list = Array.isArray(data.items) ? data.items : [];
  const entry = list[0] || null;
  const snippet = (entry && entry.snippet) || null;

  if (snippet) {
    channel_id = snippet.channelId || '';
    video_title = snippet.title || '';
  }
  if (!video_id && entry && entry.id) video_id = String(entry.id);
} catch (e) {
  resolve_error = 'Channel resolve error: ' + e.message;
}

let owner = CHANNEL_MAP[channel_id];
if (owner) {
  channel_resolved = true;
} else {
  owner = DEFAULT_OWNER;
  channel_resolved = false;
  if (!resolve_error) {
    resolve_error = channel_id
      ? ('Unknown channelId ' + channel_id + ' -- defaulting to ' + DEFAULT_OWNER)
      : ('channelId missing from videos.list response -- defaulting to ' + DEFAULT_OWNER);
  }
}

return [{
  json: {
    video_id,
    channel_id,
    owner,
    video_title,
    channel_resolved,
    resolve_error: resolve_error || null
  }
}];

// Extract best caption track ID from YouTube Data API captions.list response
// (HP variant -- Hitpoint Live owned videos, listed/downloaded with BTCHP YT Auth.)
// Selection differs from the TWS variant: prefer the auto-generated (ASR) track that
// is actively serving, because that is the track that reliably downloads for these.
const items = $input.all();
const results = [];

const kind = (t) => String((t.snippet && t.snippet.trackKind) || '').toLowerCase();
const state = (t) => String((t.snippet && t.snippet.status) || '').toLowerCase();

for (const item of items) {
  const data = item.json;
  const video_id = $('Workflow Trigger').first().json.video_id || '';

  try {
    const allTracks = data.items || [];
    // Guard: skip tracks with status 'failed' -- YouTube lists them but the download
    // is a useless ~515-byte stub even for the owning channel.
    const tracks = allTracks.filter(t => t && t.snippet && state(t) !== 'failed');
    if (tracks.length === 0) {
      const why = allTracks.length > 0
        ? 'All ' + allTracks.length + ' caption track(s) have status failed for video ' + video_id
        : 'No caption tracks found for video ' + video_id;
      results.push({ json: { video_id, captionId: '', cloud_fallback_failed: true, error: why } });
      continue;
    }

    // Filter to serving tracks first; fall back to all tracks if none are serving
    const servingTracks = tracks.filter(t => state(t) === 'serving');
    const pool = servingTracks.length > 0 ? servingTracks : tracks;

    // Priority: serving ASR track > any ASR > manual English > auto English >
    // any English-like > first available
    let best = pool.find(t => kind(t) === 'asr' && state(t) === 'serving')
      || pool.find(t => kind(t) === 'asr')
      || pool.find(t => t.snippet.language === 'en' && kind(t) !== 'asr')
      || pool.find(t => t.snippet.language === 'en' && kind(t) === 'asr')
      || pool.find(t => t.snippet.language && t.snippet.language.startsWith('en'))
      || pool[0];

    results.push({
      json: {
        captionId: best.id,
        language: best.snippet.language,
        trackKind: best.snippet.trackKind || 'standard',
        status: best.snippet.status || 'unknown',
        video_id
      }
    });
  } catch (e) {
    results.push({ json: { video_id, captionId: '', cloud_fallback_failed: true, error: 'Caption extract error: ' + e.message } });
  }
}

return results;
